import{c as r,Q as o,j as i,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Neuromorphic Computing for Low-Power Artificial Intelligence","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.04727","title":"Neuromorphic Computing for Low-Power Artificial Intelligence","archived_date":"2026-06-28","arxiv_id":"2604.04727","authors":["Keshava Katti","Pratik Chaudhari","Deep Jariwala"],"domain":"neuromorphic-computing","pdf_path":"pdfs/2604.04727.pdf","published_date":"2026-04-06","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-04-06-neuromorphic-low-power-ai-2604-04727.md","filePath":"research/papers/2026-04-06-neuromorphic-low-power-ai-2604-04727.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-04-06-neuromorphic-low-power-ai-2604-04727.md"};function n(p,e,l,c,s,m){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="neuromorphic-computing-for-low-power-artificial-intelligence" tabindex="-1">Neuromorphic Computing for Low-Power Artificial Intelligence <a class="header-anchor" href="#neuromorphic-computing-for-low-power-artificial-intelligence" aria-label="Permalink to &quot;Neuromorphic Computing for Low-Power Artificial Intelligence&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>傳統矽基計算正逼近能源效率的基本極限。本論文系統梳理神經形態計算如何提供突破路徑：</p><p><strong>核心技術支柱：</strong></p><ol><li><strong>新型元件模態</strong>（novel device modalities）：利用憶阻器（memristor）等非馮諾伊曼元件實現計算與儲存的物理整合</li><li><strong>記憶體內計算</strong>（compute-in-memory）：消除傳統 memory-compute 分離的能耗瓶頸</li><li><strong>類比動態</strong>（analog dynamics）：利用物理系統的連續態動態執行計算</li><li><strong>稀疏通訊</strong>（sparse communication）：仿腦脈衝編碼大幅降低資料搬移能耗</li></ol><p>作者強調，實現此潛力需要跨領域整合：材料科學、電路設計、架構開發、以及針對基底物理量身定制的學習演算法——而非單純替換硬體元件。</p><p>這與主流 GPU 路線形成對比：神經形態路徑以大幅降低能耗為目標（1000× 潛力），適合邊緣部署的具身 AI。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>neuromorphic 關鍵詞在既有題庫命中 <strong>0 次</strong>。Workspace 現有版圖集中於軟體層（LLM/agent），無任何硬體效率/腦啟發計算的覆蓋。</p>',9)])])}const d=r(t,[["render",n]]);export{u as __pageData,d as default};
